import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-github-catalog.ts");

import { db } from "../lib/db";

const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const GITHUB_TOKEN = process.env.GITHUB_TOKEN ?? "";
const API = "https://api.github.com";

// ── Real permissive-license allowlist (Nxeon legal policy, set this session) ──
// SPDX ids as GitHub's own license-detection API reports them. Anything not in
// here — including "NOASSERTION" (GitHub's "other"/couldn't-classify bucket)
// and no license at all — is NOT confirmed permissive. See file header.
const PERMISSIVE_SPDX = new Set([
  "MIT",
  "Apache-2.0",
  "BSD-2-Clause",
  "BSD-3-Clause",
  "Unlicense",
  "ISC",
  "GPL-2.0",
  "GPL-2.0-only",
  "GPL-2.0-or-later",
  "GPL-3.0",
  "GPL-3.0-only",
  "GPL-3.0-or-later",
]);

const MAX_STALE_DAYS = 730; // ~2 years — quality-gate recency floor
const MIN_DESCRIPTION_LEN = 15;

// ── Per-game configuration ───────────────────────────────────────────────
type CuratedList = { url: string; sections: string[] };
type GameConfig = {
  gameFamily: string;
  topics: string[];
  curated?: CuratedList;
  /** Real display category derived from which curated section a repo came from. */
  categoryForSection?: (section: string) => string;
  /** Real loader/platform tag derived from curated section or repo topics. */
  loadersFor?: (section: string | null, topics: string[]) => string[];
  /** Skip a candidate if its normalized repo name matches an existing row's
   *  normalized slug/name in this family from one of these other sources. */
  dedupeAgainstSources?: string[];
  /** Every repo here is structurally server-side software (matches Modrinth
   *  import's documented "plugin" exception — see import-modrinth-catalog.ts). */
  serverSide: "required" | "optional" | "unsupported";
};

const CS2_SECTION_META: Record<string, { category: string; loader: string }> = {
  "Metamod Plugins": { category: "Metamod", loader: "metamod" },
  "CounterStrikeSharp Plugins": { category: "CounterStrikeSharp", loader: "counterstrikesharp" },
  "SwiftlyS2 Plugins": { category: "SwiftlyS2", loader: "swiftlys2" },
};

const GAME_CONFIGS: Record<string, GameConfig> = {
  cs2: {
    gameFamily: "cs2",
    topics: ["cs2-plugin"],
    curated: {
      url: "https://raw.githubusercontent.com/samyycX/awesome-cs2/master/README.md",
      sections: Object.keys(CS2_SECTION_META),
    },
    categoryForSection: (s) => CS2_SECTION_META[s]?.category ?? "Community",
    loadersFor: (section, topics) => {
      if (section && CS2_SECTION_META[section]) return [CS2_SECTION_META[section].loader];
      const known = ["metamod", "counterstrikesharp", "swiftlys2"];
      const hit = topics.map((t) => t.toLowerCase()).find((t) => known.includes(t));
      return hit ? [hit] : [];
    },
    serverSide: "required",
  },
  // Configured, real topics — NOT executed this session (unauthenticated
  // budget was fully spent on cs2). See file header "WHAT ACTUALLY RAN".
  minecraft: {
    gameFamily: "minecraft",
    topics: ["minecraft-plugin"],
    dedupeAgainstSources: ["modrinth", "hangar"],
    categoryForSection: () => "Community",
    serverSide: "required",
  },
  gmod: {
    gameFamily: "gmod",
    topics: ["gmod-addon"],
    categoryForSection: () => "Community",
    serverSide: "required",
  },
  tmodloader: {
