    serverSide: "required",
  },
};

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  const game = get("game");
  return {
    apply: argv.includes("--apply"),
    game,
    maxCandidates: get("max-candidates") ? Number(get("max-candidates")) : undefined,
    coreSafetyMargin: Number(get("core-safety-margin") ?? 5),
  };
}

// ── GitHub REST client: real rate-limit tracking, graceful stop (not a long sleep) ──
class BudgetExhausted extends Error {}

class GhClient {
  private coreRemaining = Infinity;
  private coreResetAt = 0;
  constructor(private safetyMargin: number) {}

  private headers(): Record<string, string> {
    const h: Record<string, string> = { "User-Agent": UA, Accept: "application/vnd.github+json" };
    if (GITHUB_TOKEN) h.Authorization = `Bearer ${GITHUB_TOKEN}`;
    return h;
  }

  /** Throws BudgetExhausted rather than firing a request we already know will 403/429. */
  private checkBudget() {
    if (this.coreRemaining <= this.safetyMargin) {
      const waitS = Math.max(0, Math.round((this.coreResetAt - Date.now()) / 1000));
      throw new BudgetExhausted(
        `core rate-limit budget exhausted (remaining=${this.coreRemaining}, resets in ~${waitS}s)`
      );
    }
  }

  private track(res: Response) {
    const remaining = res.headers.get("x-ratelimit-remaining");
    const reset = res.headers.get("x-ratelimit-reset");
    if (remaining !== null) this.coreRemaining = Number(remaining);
    if (reset !== null) this.coreResetAt = Number(reset) * 1000;
  }

  /** A real, budget-tracked GET against the GitHub REST API (core quota). */
  async core(path: string): Promise<Response | null> {
    this.checkBudget();
    const res = await fetch(`${API}${path}`, { headers: this.headers() });
    this.track(res);
    if (res.status === 403 || res.status === 429) {
      // Secondary/abuse limiter or we raced past the header check — stop
      // rather than sleep out an unknown, possibly long, cooldown.
      throw new BudgetExhausted(`GitHub returned ${res.status} on ${path} — stopping rather than sleeping it out`);
    }
    return res;
  }

  /** Search quota is separate (10/min unauth) — not tracked against coreRemaining. */
  async search(path: string): Promise<Response> {
    const res = await fetch(`${API}${path}`, { headers: this.headers() });
    if (res.status === 403 || res.status === 429) {
      await new Promise((r) => setTimeout(r, 6000));
      return fetch(`${API}${path}`, { headers: this.headers() });
    }
    return res;
  }

  get remaining() {
    return this.coreRemaining;
  }
}

// ── GitHub API shapes (only fields we read) ──────────────────────────────
type GhLicense = { key: string; name: string; spdx_id: string | null } | null;
type GhOwner = { login: string; avatar_url: string };
type GhRepo = {
  full_name: string;
  name: string;
  description: string | null;
  license: GhLicense;
  pushed_at: string;
  archived: boolean;
  stargazers_count: number;
  topics?: string[];
  owner: GhOwner;
};
type GhSearchResponse = { total_count: number; items: GhRepo[] };

function classifyLicense(license: GhLicense): { raw: string | null; permissive: boolean } {
  if (!license) return { raw: null, permissive: false };
  const spdx = license.spdx_id;
  if (spdx && spdx !== "NOASSERTION" && PERMISSIVE_SPDX.has(spdx)) {
    return { raw: spdx, permissive: true };
  }
  // Never claim permissive for NOASSERTION/"other"/anything off the allowlist —
  // still store the real string GitHub reported.
  return { raw: (spdx && spdx !== "NOASSERTION" ? spdx : null) ?? license.name ?? "NOASSERTION", permissive: false };
}

function passesQualityGate(repo: GhRepo): { ok: true } | { ok: false; reason: string } {
  const desc = (repo.description ?? "").trim();
  if (desc.length < MIN_DESCRIPTION_LEN) return { ok: false, reason: `no real description (len=${desc.length})` };
  if (repo.archived) return { ok: false, reason: "archived" };
  const ageDays = (Date.now() - new Date(repo.pushed_at).getTime()) / 86_400_000;
  if (ageDays > MAX_STALE_DAYS) return { ok: false, reason: `stale (last push ${Math.round(ageDays)}d ago)` };
  return { ok: true };
}

function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80) || "mod";
}

function normalizeName(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]/g, "");
}

// ── Curated markdown list parsing (raw.githubusercontent.com — no API budget) ──
async function fetchCuratedRepos(curated: CuratedList): Promise<Map<string, { section: string; stars?: number }>> {
  const out = new Map<string, { section: string; stars?: number }>();
  const res = await fetch(curated.url, { headers: { "User-Agent": UA } });
  if (!res.ok) {
    console.warn(`  [curated] fetch failed (${res.status}) for ${curated.url} — continuing without it`);
    return out;
  }
  const text = await res.text();
  const lines = text.split("\n");
  let section: string | null = null;
  let pendingStars: number | undefined;
  for (const line of lines) {
    const h = line.match(/^##\s+(.+?)\s*$/);
    if (h) {
      section = h[1].trim();
      continue;
    }
    if (!section || !curated.sections.includes(section)) continue;
    const starMatch = line.match(/⭐\s*([\d,]+)/);
    if (starMatch) pendingStars = Number(starMatch[1].replace(/,/g, ""));
    const repoMatch = line.match(/github\.com\/([\w.-]+\/[\w.-]+)\)/);
    if (repoMatch) {
      const fullName = repoMatch[1].replace(/\.git$/, "");
      out.set(fullName.toLowerCase(), { section, stars: pendingStars });
      pendingStars = undefined;
    }
  }
  return out;
}

// ── Topic search (separate 10/min budget; returns full embedded repo objects) ──
async function fetchTopicSearch(gh: GhClient, topic: string): Promise<GhRepo[]> {
  const res = await gh.search(`/search/repositories?q=topic:${encodeURIComponent(topic)}&per_page=100`);
  if (!res.ok) {
    console.warn(`  [search] topic:${topic} → HTTP ${res.status}`);
    return [];
  }
  const body = (await res.json()) as GhSearchResponse;
  return body.items;
}

type Counters = {
  candidates: number;
  qualityFiltered: number;
  dedupedAgainstOtherSource: number;
  created: number;
  updated: number;
  upstreamGone: number;
  failed: number;
  permissive: number;
  nonPermissive: number;
  deferredBudget: number;
};
function emptyCounters(): Counters {
  return {
    candidates: 0,
    qualityFiltered: 0,
    dedupedAgainstOtherSource: 0,
    created: 0,
    updated: 0,
    upstreamGone: 0,
    failed: 0,
    permissive: 0,
    nonPermissive: 0,
    deferredBudget: 0,
  };
}

type ExistingRow = { id: string; sourceId: string | null; slug: string; name: string };

async function upsertOneRepo(opts: {
  repo: GhRepo;
  cfg: GameConfig;
  section: string | null;
  apply: boolean;
  existingBySourceId: Map<string, ExistingRow>;
  counters: Counters;
  samples: { permissive: string[]; nonPermissive: string[]; created: string[] };
}) {
  const { repo, cfg, section, apply, existingBySourceId, counters, samples } = opts;
  const key = repo.full_name.toLowerCase();
  const existing = existingBySourceId.get(key);

  const { raw: license, permissive } = classifyLicense(repo.license);
  if (permissive) {
    counters.permissive++;
    if (samples.permissive.length < 5) samples.permissive.push(`${repo.full_name} (${license})`);
  } else {
    counters.nonPermissive++;
    if (samples.nonPermissive.length < 5) samples.nonPermissive.push(`${repo.full_name} (${license ?? "none"})`);
  }

  const loaders = cfg.loadersFor?.(section, repo.topics ?? []) ?? [];
  const upstreamNote = permissive
    ? null
    : `License not confirmed permissive (GitHub reports "${license ?? "no license"}") — linked to the author's own release, not mirrored; verify before treating as redistribution-safe.`;

  if (existing) {
    // VERIFY path — never touch name/category/popularity/featured, only real
    // upstream facts (matches scripts/verify-gamemods.ts's documented scope).
    if (!apply) {
      counters.updated++;
      return;
    }
    try {
      await db.gameMod.update({
        where: { id: existing.id },
        data: {
          sourceId: repo.full_name, // keep real current casing/rename
          description: repo.description,
          iconUrl: repo.owner.avatar_url,
          authorName: repo.owner.login,
          authorAvatarUrl: repo.owner.avatar_url,
          url: `https://github.com/${repo.full_name}`,
          license,
          loaders: loaders.length ? loaders : undefined,
          serverSide: cfg.serverSide,
          verifiedAt: new Date(),
          upstreamOk: true,
          upstreamNote,
        },
      });
      counters.updated++;
    } catch (e) {
      counters.failed++;
      console.error(`  [db] update failed for ${repo.full_name}: ${e instanceof Error ? e.message : e}`);
    }
    return;
  }

  // DISCOVER path — brand-new row.
  const category = section ? (cfg.categoryForSection?.(section) ?? "Community") : "Community";
  const popularity = Math.min(repo.stargazers_count, 999);
  let slug = slugify(repo.name);

  if (!apply) {
    counters.created++;
    if (samples.created.length < 8) samples.created.push(`${repo.full_name} → slug "${slug}"`);
    return;
  }

  try {
    // Slug collision avoidance: (gameFamily, slug) is the real unique
    // constraint, and two different repos can share a bare repo name.
    for (let attempt = 0; attempt < 3; attempt++) {
      const clash = await db.gameMod.findUnique({
        where: { gameFamily_slug: { gameFamily: cfg.gameFamily, slug } },
        select: { sourceId: true },
      });
      if (!clash) break;
      if (clash.sourceId?.toLowerCase() === key) break; // race with a prior iteration of this same repo
      const ownerSlug = slugify(repo.full_name.split("/")[0] ?? "");
      slug = attempt === 0 ? `${slug}-${ownerSlug}` : `${slug}-${ownerSlug}-${attempt}`;
    }

    await db.gameMod.create({
      data: {
        gameFamily: cfg.gameFamily,
        slug,
        name: repo.name,
        category,
        source: "github",
        sourceId: repo.full_name,
        url: `https://github.com/${repo.full_name}`,
        description: repo.description,
        iconUrl: repo.owner.avatar_url,
        authorName: repo.owner.login,
        authorAvatarUrl: repo.owner.avatar_url,
        popularity,
        license,
        loaders,
        serverSide: cfg.serverSide,
        verifiedAt: new Date(),
        upstreamOk: true,
        upstreamNote,
        active: true,
      },
    });
    counters.created++;
    if (samples.created.length < 8) samples.created.push(`${repo.full_name} → slug "${slug}"`);
  } catch (e) {
    counters.failed++;
    console.error(`  [db] create failed for ${repo.full_name}: ${e instanceof Error ? e.message : e}`);
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.game || !GAME_CONFIGS[args.game]) {
    console.error(`Usage: --game=<${Object.keys(GAME_CONFIGS).join("|")}> [--apply] [--max-candidates=N] [--core-safety-margin=N]`);
    process.exit(1);
  }
  const cfg = GAME_CONFIGS[args.game];
  console.log(
    `[import-github-catalog] game=${args.game} gameFamily=${cfg.gameFamily} ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} ` +
      `— ${GITHUB_TOKEN ? "authenticated (5000/hr core)" : "UNAUTHENTICATED (60/hr core)"}${args.maxCandidates ? `; max-candidates=${args.maxCandidates}` : ""}`
  );

  const gh = new GhClient(args.coreSafetyMargin);
  const counters = emptyCounters();
  const samples = { permissive: [] as string[], nonPermissive: [] as string[], created: [] as string[] };

  // ── Build the candidate set ────────────────────────────────────────────
  // section: which curated section (if any) a repo came from — drives category/loaders.
  const candidates = new Map<string, { section: string | null; repo?: GhRepo }>();

  if (cfg.curated) {
    console.log(`\n[curated] fetching ${cfg.curated.url}`);
    const curatedRepos = await fetchCuratedRepos(cfg.curated);
    console.log(`[curated] ${curatedRepos.size} real repos across sections: ${cfg.curated.sections.join(", ")}`);
    for (const [key, { section }] of curatedRepos) candidates.set(key, { section });
  }

  for (const topic of cfg.topics) {
    console.log(`\n[search] topic:${topic}`);
    const hits = await fetchTopicSearch(gh, topic);
    console.log(`[search] topic:${topic} → ${hits.length} real repos (embedded metadata, no core budget spent)`);
    for (const repo of hits) {
      const key = repo.full_name.toLowerCase();
      const existingCand = candidates.get(key);
      candidates.set(key, { section: existingCand?.section ?? null, repo });
    }
  }
  counters.candidates = candidates.size;
  console.log(`\n[merge] ${candidates.size} unique candidate repos (curated ∪ search) for ${args.game}`);

  // ── Existing DB rows for this family/source (for VERIFY matching) ─────
  const existingGithubRows = await db.gameMod.findMany({
    where: { gameFamily: cfg.gameFamily, source: "github" },
    select: { id: true, sourceId: true, slug: true, name: true },
  });
  const existingBySourceId = new Map<string, ExistingRow>();
  for (const row of existingGithubRows) {
    if (row.sourceId) existingBySourceId.set(row.sourceId.toLowerCase(), row);
  }
  console.log(`[existing] ${existingGithubRows.length} github-sourced ${cfg.gameFamily} rows already in the DB`);
  // Make sure every existing row gets a VERIFY pass even if it dropped out of
  // both the curated list and topic search this time around (e.g. it stopped
  // shipping a description, or just isn't topic-tagged) — its repo data still
  // needs a real /repos call.
  for (const row of existingGithubRows) {
    const key = row.sourceId?.toLowerCase();
    if (key && !candidates.has(key)) candidates.set(key, { section: null });
  }

  // ── Dedupe against other sources in the same family ────────────────────
  let dedupeNames: Set<string> | null = null;
  if (cfg.dedupeAgainstSources?.length) {
    const otherRows = await db.gameMod.findMany({
      where: { gameFamily: cfg.gameFamily, source: { in: cfg.dedupeAgainstSources } },
      select: { slug: true, name: true },
    });
    dedupeNames = new Set(otherRows.flatMap((r) => [normalizeName(r.slug), normalizeName(r.name)]));
    console.log(`[dedupe] ${dedupeNames.size} normalized names from ${cfg.dedupeAgainstSources.join("/")} to skip against`);
  }

  // ── Priority order: existing rows first (verify), then repos with free
  // search-embedded data (zero extra core cost), then curated-only repos
  // (need one real /repos call each) — the exact order this session's rate-
  // limit math above assumed. ────────────────────────────────────────────
  const ordered = [...candidates.entries()].sort((a, b) => {
    const score = (v: { section: string | null; repo?: GhRepo }, key: string) => {
      if (existingBySourceId.has(key)) return 0; // verify first
      if (v.repo) return 1; // free data
      return 2; // needs a /repos call
    };
    return score(a[1], a[0]) - score(b[1], b[0]);
  });

  let stoppedOnBudget = false;
  let processed = 0;
  for (const [key, { section, repo: embeddedRepo }] of ordered) {
    if (args.maxCandidates !== undefined && processed >= args.maxCandidates) {
      console.log(`\n[stop] --max-candidates=${args.maxCandidates} reached`);
      break;
    }
    processed++;

    let repo = embeddedRepo;
    if (!repo) {
      // Curated-only repo — needs a real, budget-tracked GET.
      let res: Response | null;
      try {
        res = await gh.core(`/repos/${key}`);
      } catch (e) {
        if (e instanceof BudgetExhausted) {
          console.warn(`\n[budget] ${e.message} — stopping here, ${candidates.size - processed + 1} candidates deferred`);
          stoppedOnBudget = true;
          break;
        }
        throw e;
      }
      if (!res) continue;
      if (res.status === 404) {
        const existing = existingBySourceId.get(key);
        if (existing) {
          counters.upstreamGone++;
          if (args.apply) {
            await db.gameMod.update({
              where: { id: existing.id },
              data: { upstreamOk: false, upstreamNote: "repo not found on GitHub (removed, renamed, or made private)", verifiedAt: new Date() },
            });
          }
        }
        continue;
      }
      if (!res.ok) {
        counters.failed++;
        console.warn(`  [repo] ${key} → HTTP ${res.status}`);
        continue;
      }
      repo = (await res.json()) as GhRepo;
    }

    const gate = passesQualityGate(repo);
    const isNew = !existingBySourceId.has(key);
    if (isNew && !gate.ok) {
      counters.qualityFiltered++;
      continue;
    }

    if (isNew && dedupeNames) {
      const norm = normalizeName(repo.name);
      if (dedupeNames.has(norm)) {
        counters.dedupedAgainstOtherSource++;
        continue;
      }
    }

    await upsertOneRepo({ repo, cfg, section, apply: args.apply, existingBySourceId, counters, samples });
  }
  if (stoppedOnBudget) counters.deferredBudget = candidates.size - processed + 1;

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY — game=${args.game} (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  console.log(`  candidates considered   : ${counters.candidates}`);
  console.log(`  quality-gate filtered   : ${counters.qualityFiltered}`);
  console.log(`  deduped vs other source : ${counters.dedupedAgainstOtherSource}`);
  console.log(`  created                 : ${counters.created}`);
  console.log(`  updated (verified)      : ${counters.updated}`);
  console.log(`  upstream gone (404)     : ${counters.upstreamGone}`);
  console.log(`  failed                  : ${counters.failed}`);
  console.log(`  license: permissive     : ${counters.permissive}  (sample: ${samples.permissive.join("; ") || "none"})`);
  console.log(`  license: NOT confirmed  : ${counters.nonPermissive}  (sample: ${samples.nonPermissive.join("; ") || "none"})`);
  if (samples.created.length) console.log(`  sample new rows         : ${samples.created.join("; ")}`);
  if (stoppedOnBudget) console.log(`  STOPPED ON RATE-LIMIT BUDGET — ${counters.deferredBudget} candidates deferred, real GitHub core remaining=${gh.remaining}`);
  console.log(`  GitHub core remaining   : ${gh.remaining}`);
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

